以下带参数的类装饰器 CountCalls 实现调用计数，调用 add(1,2) 两次后，访问 add.count 的值是？
```python
class CountCalls:
    def __init__(self, func):
        self.func = func
        self.count = 0
    def __call__(self, *args):
        self.count += 1
        return self.func(*args)
@CountCalls
def add(a, b):
    return a + b
add(1,2)
add(3,4)
print(add.count)
```

设计一个带参数装饰器 require_role(role)，检查用户角色。装饰后函数名为？
```python
from functools import wraps
def require_role(role):
    def decorator(func):
        @wraps(func)
        def wrapper(user, *args):
            if user['role'] != role:
                raise PermissionError
            return func(user, *args)
        return wrapper
    return decorator
@require_role('admin')
def delete_user(user, uid):
    """delete a user"""
    pass
print(delete_user.__name__)
```
